import{_ as l,o as e,c as i,a2 as o}from"./chunks/framework.C4u7U0Dw.js";const _=JSON.parse('{"title":"MomaWork 助手阅读与学习指南：从入门到团队落地","description":"","frontmatter":{},"headers":[],"relativePath":"阅读指南.md","filePath":"阅读指南.md"}'),r={name:"阅读指南.md"};function t(n,a,h,s,d,p){return e(),i("div",null,[...a[0]||(a[0]=[o('<h1 id="momawork-助手阅读与学习指南-从入门到团队落地" tabindex="-1">MomaWork 助手阅读与学习指南：从入门到团队落地 <a class="header-anchor" href="#momawork-助手阅读与学习指南-从入门到团队落地" aria-label="Permalink to &quot;MomaWork 助手阅读与学习指南：从入门到团队落地&quot;">​</a></h1><p>这是一条面向新手、任务实践者和团队负责人的学习路线。你不必从头背功能：先找到当前最接近的工作问题，完成一项真实任务，再沿着使用手册、实战案例、进阶系统和团队落地逐步深入。</p><h2 id="新手入门路线" tabindex="-1">新手入门路线 <a class="header-anchor" href="#新手入门路线" aria-label="Permalink to &quot;新手入门路线&quot;">​</a></h2><p>从<a href="./bluebook/第一篇 使用手册：先把我用起来/">第一篇：先把我用起来</a>开始，依次完成：</p><ol><li>认识 momawork-rs：我是什么、能做什么、边界在哪里。</li><li>发出第一次对话，学会如何把需求讲清楚。</li><li>完成第一个可检查的任务（写一份文档、跑一条命令）。</li><li>加载一个真正用得上的 Skill。</li><li>再学习记忆系统、计划模式与 AI 团队。</li></ol><p>建议边读边做，不要只浏览文字。每完成一章，至少留下一个可复用的提示词、模板或操作记录。</p><h2 id="按真实任务选择教程" tabindex="-1">按真实任务选择教程 <a class="header-anchor" href="#按真实任务选择教程" aria-label="Permalink to &quot;按真实任务选择教程&quot;">​</a></h2><p>直接进入<a href="./bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/">第二篇：案例篇</a>，按问题选择章节：</p><ul><li>写报告、方案、白皮书：第 9 章。</li><li>写代码、改 bug、跑脚本：第 10 章。</li><li>整理电脑文件、批量重命名：第 11 章。</li><li>数据清洗、分析与可视化：第 12 章。</li><li>知识管理、资讯整合、自动化与团队协作：第 13～16 章。</li></ul><p>案例跑通后，再回到第三篇，把你的做法整理为 Skill、自动化或多 Agent 系统。</p><h2 id="团队落地路线" tabindex="-1">团队落地路线 <a class="header-anchor" href="#团队落地路线" aria-label="Permalink to &quot;团队落地路线&quot;">​</a></h2><p>重点阅读<a href="./bluebook/第三篇 进阶篇：把案例变成自己的工作系统/">第三篇：进阶篇</a>与<a href="./bluebook/第四篇 岗位与行业落地/">第四篇：岗位与行业落地</a>。</p><p>团队实践建议同时记录：</p><ul><li>输入资料和权限边界。</li><li>任务拆解方式和失败回退。</li><li>交付物的验收标准。</li><li>可以复用的 Skill、模板和自动化。</li><li>哪些步骤必须由人确认。</li></ul><h2 id="发现内容可以改进" tabindex="-1">发现内容可以改进 <a class="header-anchor" href="#发现内容可以改进" aria-label="Permalink to &quot;发现内容可以改进&quot;">​</a></h2><p>欢迎通过 Issue 提出问题，或直接修改对应 Markdown 页面，参与共创。</p>',16)])])}const c=l(r,[["render",t]]);export{_ as __pageData,c as default};
